// Astrea SecOps SOAR - Risk Score Calculation Node
// Ponderation formula: RiskScore = (CTI_Score * 0.4) + (CVSS * 0.6 * 10)
// Normalization range: 0.0 - 100.0

const items = $input.all();
const results = [];

for (const item of items) {
  // 1. Extract alert context from Webhook Trigger
  const webhookData = $('Webhook Trigger').first().json.body || {};
  const src_ip = webhookData.src_ip || '127.0.0.1';
  const dst_ip = webhookData.dst_ip || '127.0.0.1';
  const agent_id = webhookData.agent_id || '';
  const software_banner = webhookData.software_banner || '';
  const alert_name = webhookData.alert_name || 'Suspicious Activity Detected';
  const rule_id = webhookData.rule_id || 'ASTREA-RULE-001';
  const dst_port = webhookData.dst_port ? parseInt(webhookData.dst_port, 10) : 80;

  // 2. Extract CTI AbuseIPDB reputation score (0-100)
  let CTI_Score = 0;
  let src_country = 'UNKNOWN';
  try {
    const ctiResponse = $('CTI Reputation Lookup').first().json;
    if (ctiResponse && ctiResponse.data && typeof ctiResponse.data.abuseConfidenceScore === 'number') {
      CTI_Score = ctiResponse.data.abuseConfidenceScore;
      src_country = ctiResponse.data.countryCode || src_country;
    } else if (ctiResponse && typeof ctiResponse.abuseConfidenceScore === 'number') {
      CTI_Score = ctiResponse.abuseConfidenceScore;
      src_country = ctiResponse.countryCode || src_country;
    } else if (ctiResponse && typeof ctiResponse.cti_score === 'number') {
      CTI_Score = ctiResponse.cti_score;
    } else if (webhookData.src_reputation_score !== undefined) {
      CTI_Score = parseInt(webhookData.src_reputation_score, 10) || 0;
    }
  } catch (err) {
    // Fallback reputation score when AbuseIPDB is unavailable
    CTI_Score = (rule_id.includes('10002') || rule_id.includes('10003')) ? 80 : 15;
  }

  // 3. Extract CVSS vulnerability score (0.0-10.0) from NVD check
  let CVSS = 0.0;
  let associated_cve = '';
  let cve_description = '';
  try {
    const nvdResponse = $('NVD Vulnerability Check').first().json;
    if (nvdResponse && Array.isArray(nvdResponse.vulnerabilities) && nvdResponse.vulnerabilities.length > 0) {
      for (const vuln of nvdResponse.vulnerabilities) {
        const score = parseFloat(vuln.cvss_score) || 0.0;
        if (score >= CVSS) {
          CVSS = score;
          associated_cve = vuln.cve_id || associated_cve;
          cve_description = vuln.description || cve_description;
        }
      }
    } else if (nvdResponse && nvdResponse.cvss_score) {
      CVSS = parseFloat(nvdResponse.cvss_score) || 0.0;
      associated_cve = nvdResponse.cve_id || '';
    }
  } catch (err) {
    CVSS = 0.0;
  }

  // Fallback signature mapping for common lab banners
  if (CVSS === 0.0 && software_banner) {
    if (software_banner.includes('2.4.49')) {
      CVSS = 9.8;
      associated_cve = 'CVE-2021-41773';
      cve_description = 'Apache 2.4.49 Path Traversal and Remote Code Execution';
    } else if (software_banner.includes('1.18.0')) {
      CVSS = 7.5;
      associated_cve = 'CVE-2021-23017';
    }
  }

  // 4. Calculate Risk Score using composite formula:
  // RiskScore = (CTI_Score * 0.4) + (CVSS * 0.6 * 10)
  const rawRiskScore = (CTI_Score * 0.4) + (CVSS * 0.6 * 10);

  // 5. Normalize score strictly between 0.0 and 100.0
  let RiskScore = Math.min(100.0, Math.max(0.0, rawRiskScore));
  RiskScore = Math.round(RiskScore * 10) / 10;

  // 6. Classification: If RiskScore >= 80.0, severity = 'CRITICAL' & should_contain = true
  let severity = 'LOW';
  let should_contain = false;

  if (RiskScore >= 80.0) {
    severity = 'CRITICAL';
    should_contain = true;
  } else if (RiskScore >= 60.0) {
    severity = 'HIGH';
  } else if (RiskScore >= 40.0) {
    severity = 'MEDIUM';
  } else {
    severity = 'LOW';
  }

  results.push({
    json: {
      alert_name,
      rule_id,
      src_ip,
      src_country,
      dst_ip,
      dst_port,
      agent_id,
      software_banner,
      associated_cve: associated_cve || null,
      cve_description: cve_description || null,
      cti_score: CTI_Score,
      cvss_score: CVSS,
      risk_score: RiskScore,
      raw_risk_score: rawRiskScore,
      severity,
      should_contain,
      status: 'ENRICHED',
      timestamp: new Date().toISOString()
    }
  });
}

return results;
